param([switch]$Open)
$root=Split-Path -Parent (Split-Path -Parent $PSCommandPath);$need=@('PROTOCOL.md','fixture/package-lock.json','fixture/database/schema/001_inventory.sql','prompts/S01.txt','prompts/S02.txt','execution-order.json','runner/Evaluate.ps1','calibration/CALIBRATION-SUMMARY.json','qualification/QUALIFICATION-SUMMARY.json');$missing=$need|Where-Object{-not(Test-Path (Join-Path $root $_))};if($missing){throw "Missing gate inputs: $($missing-join ', ')"};$cal=Get-Content (Join-Path $root 'calibration/CALIBRATION-SUMMARY.json')-Raw|ConvertFrom-Json;$qual=Get-Content (Join-Path $root 'qualification/QUALIFICATION-SUMMARY.json')-Raw|ConvertFrom-Json;if($cal.result-ne'PASS'-or$qual.result-ne'PASS'){throw 'Gate inputs are not green'};$state=Join-Path $root 'official-launch-state.json';if(-not(Test-Path $state)){if(-not$Open){throw 'Gate closed'};[ordered]@{gate='OPEN';officialLaunchCount=0;maximumOfficialLaunches=4;order=(Get-Content (Join-Path $root 'execution-order.json')-Raw|ConvertFrom-Json).order}|ConvertTo-Json|Set-Content $state};Get-Content $state -Raw
